public sealed class OrderRepository(ShopDb db)
{
    // Looks more abstract, but every operator added later runs in memory
    public IEnumerable<Order> GetAll() => db.Orders;
}

public sealed class OrderService(OrderRepository orders)
{
    // SQL sent: SELECT ... FROM "Orders" (no WHERE, no LIMIT)
    public List<Order> Latest(int customerId) => orders.GetAll()
        .Where(o => o.CustomerId == customerId) // Enumerable.Where, in C#
        .OrderByDescending(o => o.CreatedAt)
        .Take(10)
        .ToList();
}

using Microsoft.EntityFrameworkCore;

public sealed class OrderRepository(ShopDb db)
{
    // SQL sent: WHERE, ORDER BY and LIMIT all reach the database
    public Task<List<Order>> LatestAsync(int customerId, int count,
        CancellationToken ct) => db.Orders
            .Where(o => o.CustomerId == customerId) // Queryable.Where, in SQL
            .OrderByDescending(o => o.CreatedAt)
            .Take(count)
            .AsNoTracking()
            .ToListAsync(ct);
}
